# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SANTRİFÜJ TÜPÜNDE KANIN YAPISI VE GÖREVLERİ (FB.7.3.3)</text>\n  <rect x="30" y="50" width="140" height="185" rx="10" fill="#ffffff" stroke="#64748b" stroke-width="2"/>\n  <rect x="34" y="54" width="132" height="98" rx="6" fill="#fef08a"/>\n  <text x="100" y="95" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">%55 KAN PLAZMASI</text>\n  <text x="100" y="115" text-anchor="middle" font-size="10.5" fill="#713f12">(%90 Su + %10 Besin,</text>\n  <text x="100" y="130" text-anchor="middle" font-size="10.5" fill="#713f12">Hormon, Antikor, Atık)</text>\n  <rect x="34" y="152" width="132" height="16" fill="#e2e8f0"/>\n  <text x="100" y="164" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#334155">Akyuvar ve Kan Pulcukları</text>\n  <rect x="34" y="168" width="132" height="63" rx="6" fill="#ef4444"/>\n  <text x="100" y="198" text-anchor="middle" font-size="12" font-weight="bold" fill="#ffffff">%45 KAN HÜCRELERİ</text>\n  <text x="100" y="216" text-anchor="middle" font-size="10.5" fill="#fee2e2">Alyuvar (O2 ve CO2 taşır)</text>\n  <rect x="195" y="50" width="480" height="56" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="210" y="72" font-size="12" font-weight="bold" fill="#b91c1c">1. Alyuvar (Kırmızı Kan Hücresi — En Fazla Sayıda):</text>\n  <text x="210" y="92" font-size="11" fill="#334155">Yapısındaki hemoglobin ile O2 ve CO2 taşır. Olgunlaşınca çekirdeğini kaybeder.</text>\n  <rect x="195" y="114" width="480" height="56" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="210" y="136" font-size="12" font-weight="bold" fill="#1d4ed8">2. Akyuvar (Beyaz Kan Hücresi — En Büyük ve Çekirdekli):</text>\n  <text x="210" y="156" font-size="11" fill="#334155">Vücudu mikroplara karşı savunur (fagositoz yapar veya antikor üretir). Hastalıkta sayısı artar.</text>\n  <rect x="195" y="178" width="480" height="56" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="210" y="200" font-size="12" font-weight="bold" fill="#a16207">3. Kan Pulcukları (Trombosit — En Küçük ve Renksiz):</text>\n  <text x="210" y="220" font-size="11" fill="#334155">Yaralanma ve kesiklerde kanın pıhtılaşmasını sağlayarak kan kaybını önler.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KAN GRUPLARI, Rh FAKTÖRÜ VE KAN BAĞIŞI (FB.7.3.4)</text>\n  <rect x="25" y="48" width="320" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">ABO ve Rh Kan Grubu Sistemi</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• A Grubu: Alyuvarda A proteini bulunur.</text>\n  <text x="40" y="120" font-size="11" fill="#334155">• B Grubu: Alyuvarda B proteini bulunur.</text>\n  <text x="40" y="142" font-size="11" fill="#334155">• AB Grubu: A ve B proteini birlikte bulunur.</text>\n  <text x="40" y="164" font-size="11" fill="#334155">• 0 (Sıfır) Grubu: A ve B proteini bulunmaz.</text>\n  <text x="40" y="190" font-size="11" font-weight="bold" fill="#1e40af">• Rh(+): Rh proteini var | Rh(-): Rh proteini yok</text>\n  <text x="185" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Esas Kural: Herkes Kendi Grubuyla Alışveriş Yapar!</text>\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Türk Kızılayı ve Kan Bağışı Şartları</text>\n  <text x="380" y="98" font-size="11" fill="#334155">• Yaş sınırı: 18 - 65 yaş arası sağlıklı bireyler</text>\n  <text x="380" y="120" font-size="11" fill="#334155">• Kütle sınırı: 50 kg ve üzeri ağırlıkta olmak</text>\n  <text x="380" y="142" font-size="11" fill="#334155">• Bulaşıcı hastalığı ve kansızlığı bulunmamak</text>\n  <text x="380" y="164" font-size="11" fill="#334155">• 1 ünite kan bağışı 3 kişinin hayatını kurtarır</text>\n  <text x="380" y="186" font-size="11" fill="#334155">• Kemik iliği uyarılarak kan hücreleri yenilenir</text>\n  <text x="520" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">Toplumsal Dayanışma ve Yardımlaşma Güçlenir</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DOLAŞIM SİSTEMİNİN SAĞLIĞI VE HASTALIKLARI (FB.7.3.5)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Sağlığı Koruma İlkeleri</text>\n  <text x="40" y="98" font-size="11.5" fill="#334155">• Yeterli, dengeli ve doğal beslenmek</text>\n  <text x="40" y="122" font-size="11.5" fill="#334155">• Yaş ve fiziğe uygun düzenli egzersiz yapmak</text>\n  <text x="40" y="146" font-size="11.5" fill="#334155">• Sigara, alkol ve zararlı maddelerden uzak durmak</text>\n  <text x="40" y="170" font-size="11.5" fill="#334155">• Aşırı stres, hareketsizlik ve obeziteden kaçınmak</text>\n  <text x="40" y="194" font-size="11.5" fill="#334155">• Dar giysiler giymemek, temiz hava almak</text>\n  <text x="182" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Sağlıklı Damar = Sağlıklı Kalp</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Başlıca Dolaşım Hastalıkları ve Tedaviler</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Anemi (Kansızlık): Alyuvar / demir eksikliği</text>\n  <text x="375" y="120" font-size="11" fill="#334155">• Damar Tıkanıklığı ve Kalp Krizi (Enfarktüs)</text>\n  <text x="375" y="142" font-size="11" fill="#334155">• Yüksek Tansiyon (Hipertansiyon) ve Varis</text>\n  <text x="375" y="164" font-size="11" fill="#334155">• Lösemi (Kan kanseri) ve Hemofili (Pıhtılaşmama)</text>\n  <text x="375" y="186" font-size="11" fill="#334155">• Tedavi: Anjiyo, Stent, Kalp Pili, Bypass</text>\n  <text x="517" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Erken Teşhis ve Düzenli Doktor Kontrolü</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
